def block(net,extra):
 blocked=[set(),set()]
 for shape,n,layers,g in copper:
  if n==net:continue
  if shape=='rect':x1,y1,x2,y2=g;rad=extra
  else:x1,y1,x2,y2,r=g;rad=r+extra
