     dx=x2-x1;dy=y2-y1;t=max(0,min(1,((x-x1)*dx+(y-y1)*dy)/(dx*dx+dy*dy))) if dx or dy else 0;d=math.hypot(x-x1-t*dx,y-y1-t*dy)
